import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { randomIntBetween } from 'https://jslib.k6.io/k6-utils/1.4.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailureRate = new Rate('business_failure');
const businessResponses = new Counter('business_responses');
const unexpectedFailures = new Counter('unexpected_failures');

const USERS = 2;
const ITERATIONS = 2;

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '5m',
    },
  },
  thresholds: {
    http_req_duration: ['p(95)<5000'],
    http_req_failed: ['rate<0.5'],
  },
};

function getCsrfFromForm(html) {
  const match = html.match(/<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (match) return match[1];
  const match2 = html.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  if (match2) return match2[1];
  const match3 = html.match(/<input[^>]*name=["']csrf["'][^>]*>/i);
  if (match3) {
    const valMatch = match3[0].match(/value=["']([^"']+)["']/i);
    if (valMatch) return valMatch[1];
  }
  const allInputs = html.match(/<input[^>]*>/gi) || [];
  for (const input of allInputs) {
    if (/name=["']csrf["']/i.test(input)) {
      const valMatch = input.match(/value=["']([^"']+)["']/i);
      if (valMatch) return valMatch[1];
    }
  }
  return null;
}

function getChallengeFromForm(html) {
  const match = html.match(/<input[^>]*name=["']challenge["'][^>]*value=["']([^"']+)["']/i);
  if (match) return match[1];
  const match2 = html.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']challenge["']/i);
  if (match2) return match2[1];
  const allInputs = html.match(/<input[^>]*>/gi) || [];
  for (const input of allInputs) {
    if (/name=["']challenge["']/i.test(input)) {
      const valMatch = input.match(/value=["']([^"']+)["']/i);
      if (valMatch) return valMatch[1];
    }
  }
  return null;
}

function getFormAction(html) {
  const match = html.match(/<form[^>]*action=["']([^"']+)["']/i);
  return match ? match[1] : null;
}

function getLocationFromHeaders(headers) {
  const loc = headers['Location'];
  if (loc) return loc;
  return null;
}

function getETagFromHeaders(headers) {
  const etag = headers['ETag'] || headers['Etag'] || headers['etag'];
  if (etag) return etag;
  return null;
}

function getCsrfFromJson(body) {
  try {
    const json = JSON.parse(body);
    if (json && json.csrf) return json.csrf;
  } catch (e) {
    // ignore
  }
  return null;
}

function getGrantIdFromJson(body) {
