function getSessionCookieFromResponse(res) {
  const setCookies = res.headers['Set-Cookie'] || [];
  for (const cookie of setCookies) {
    if (cookie.startsWith('session=') || cookie.startsWith('sessionid=')) {
      return cookie.split(';')[0];
    }
  }
  return null;
}

function getCookieValue(cookieStr) {
  if (!cookieStr) return null;
  const parts = cookieStr.split('=');
  if (parts.length >= 2) return parts.slice(1).join('=');
  return null;
}

function getCookieName(cookieStr) {
  if (!cookieStr) return null;
  return cookieStr.split('=')[0];
}

function makeRequest(method, url, params, body) {
  const res = http.request(method, url, body, params);
  return res;
}

function recordBusinessResponse(res, expectedExpiry = false, expectedScheduled429 = false) {
  businessResponses.add(1);
  if (res.status === 500) {
    unexpectedFailures.add(1);
    businessFailureRate.add(1);
    return;
  }
  if (res.status === 401) {
    const err = getErrorFromJson(res.body);
    if (err === 'expired' && expectedExpiry) {
      // expected expiry, not a failure
      return;
    }
    if (err === 'denied') {
      unexpectedFailures.add(1);
      businessFailureRate.add(1);
      return;
    }
    if (err === 'session') {
      // session revoked, not a business failure per se
      return;
    }
    unexpectedFailures.add(1);
    businessFailureRate.add(1);
    return;
  }
  if (res.status === 429 && expectedScheduled429) {
    // expected scheduled 429
    return;
  }
  if (res.status >= 400) {
    unexpectedFailures.add(1);
    businessFailureRate.add(1);
    return;
  }
  // success
}

function doWork() {
  const params = {
    headers: {
      'Content-Type': 'application/json',
    },
  };
  let res = makeRequest('POST', `${BASE_URL}/v2/work`, params, JSON.stringify({}));
  let retries = 0;
  while (res.status === 429 && retries < 4) {
    const retryAfter = getRetryAfterFromHeaders(res.headers);
    const waitTime = retryAfter || 1;
    sleep(waitTime);
    res = makeRequest('POST', `${BASE_URL}/v2/work`, params, JSON.stringify({}));
    retries++;
  }
  recordBusinessResponse(res, false, false);
  const ok = getOkFromJson(res.body);
  check(res, {
    'work returns 200': (r) => r.status === 200,
    'work returns ok': () => ok === true,
  });
}

function doBrowse() {
