function loginFlow(userIndex) {
  const username = `bench-${userIndex}`;
  const password = 'bench';

  // Step 1: GET login form
  const formRes = makeRequest('GET', `${BASE_URL}/v2/login-form`, { redirects: 0 }, null);
  check(formRes, {
    'login form returns 200': (r) => r.status === 200,
  });
  if (formRes.status !== 200) {
    return null;
  }

  const csrf = getCsrfFromForm(formRes.body);
  check(csrf, {
    'csrf extracted from form': (c) => c !== null && c.length > 0,
  });
  if (!csrf) {
    return null;
  }

  // Step 2: POST login
  const loginParams = {
    headers: {
      'Content-Type': 'application/json',
    },
    redirects: 0,
  };
  const loginBody = JSON.stringify({ username, password, csrf });
  let loginRes = makeRequest('POST', `${BASE_URL}/v2/login`, loginParams, loginBody);

  // Handle 302 redirect
  if (loginRes.status === 302) {
    const location = getLocationFromHeaders(loginRes.headers);
    if (location) {
      const redirectUrl = location.startsWith('http') ? location : `${BASE_URL}${location}`;
      loginRes = makeRequest('GET', redirectUrl, { redirects: 0 }, null);
    }
  }

  check(loginRes, {
    'login succeeds': (r) => r.status === 200 || r.status === 201 || r.status === 302,
  });

  if (loginRes.status !== 200 && loginRes.status !== 201 && loginRes.status !== 302) {
    return null;
  }

  let sessionCookie = getSessionCookieFromResponse(loginRes);
  let currentCsrf = getCsrfFromJson(loginRes.body) || csrf;

  // If login returned 302 and we followed it, check for session cookie in the redirect response
  if (!sessionCookie && loginRes.status === 200) {
    // try to get from headers
    sessionCookie = getSessionCookieFromResponse(loginRes);
  }

  // If still no session cookie, try to get from the original login response
  if (!sessionCookie) {
    // The session cookie might have been set on the 302 response
    // We need to check the original response
    // For k6, we can't easily get the original response after following redirect
    // So we'll try to get it from the current response
    sessionCookie = getSessionCookieFromResponse(loginRes);
  }

  if (!sessionCookie) {
    // Try to get session cookie from the form response
    sessionCookie = getSessionCookieFromResponse(formRes);
  }

  return {
    username,
    password,
    csrf: currentCsrf,
    sessionCookie,
    userId: getUserIdFromJson(loginRes.body),
  };
}

function renewSession(sessionCookie, currentCsrf) {
  const params = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf,
    },
  };
  if (sessionCookie) {
    params.headers['Cookie'] = sessionCookie;
  }
  const res = makeRequest('POST', `${BASE_URL}/v2/session/renew`, params, JSON.stringify({}));
  const newCsrf = getCsrfFromJson(res.body) || currentCsrf;
  const newSessionCookie = getSessionCookieFromResponse(res) || sessionCookie;
  return {
    res,
    csrf: newCsrf,
    sessionCookie: newSessionCookie,
  };
}

