function handle401Expired(sessionCookie, currentCsrf, cartId, operationFn) {
  // Renew session
  const renewResult = renewSession(sessionCookie, currentCsrf);
  let newCsrf = renewResult.csrf;
  let newSessionCookie = renewResult.sessionCookie;

  // Recover cart if exists
  if (cartId) {
    const recoverResult = recoverCart(newSessionCookie, newCsrf, cartId);
    newCsrf = recoverResult.csrf;
  }

  // Retry the operation once
  const retryResult = operationFn(newSessionCookie, newCsrf);
  return {
    res: retryResult,
    csrf: newCsrf,
    sessionCookie: newSessionCookie,
  };
}

function handle401Session(sessionCookie, currentCsrf, cartId, userIndex, operationFn) {
  // Session revoked: get fresh form/login, recover cart
  const freshLogin = loginFlow(userIndex);
  if (!freshLogin) {
    return {
      res: null,
      csrf: currentCsrf,
      sessionCookie: sessionCookie,
      failed: true,
    };
  }
  let newCsrf = freshLogin.csrf;
  let newSessionCookie = freshLogin.sessionCookie;

  if (cartId) {
    const recoverResult = recoverCart(newSessionCookie, newCsrf, cartId);
    newCsrf = recoverResult.csrf;
  }

  const retryResult = operationFn(newSessionCookie, newCsrf);
  return {
    res: retryResult,
    csrf: newCsrf,
    sessionCookie: newSessionCookie,
    failed: false,
  };
}

function shopJourney(userIndex) {
  // Fresh login
  const login = loginFlow(userIndex);
  if (!login) {
    return false;
  }

  let sessionCookie = login.sessionCookie;
  let currentCsrf = login.csrf;
  let cartId = null;
  let cartEtag = null;
  let grantId = null;
  let reservationId = null;
  let orderPlaced = false;

  // Step: Get catalog
  let catalogRes = getCatalog(sessionCookie, currentCsrf);
  recordBusinessResponse(catalogRes, false, false);
  check(catalogRes, {
    'catalog returns 200': (r) => r.status === 200,
  });

  if (catalogRes.status !== 200) {
    return false;
  }

  let products = getProductsFromCatalog(catalogRes.body);
  let selectedProduct = null;
  let selectedVariant = null;

  if (products.length > 0) {
    selectedProduct = products[0];
    if (selectedProduct.variants && selectedProduct.variants.length > 0) {
      selectedVariant = selectedProduct.variants[0];
    }
  }

  // If no products from catalog, try catalog/page
  if (!selectedProduct || !selectedVariant) {
    let pageUrl = '/v2/catalog/page';
    let pagesTraversed = 0;
    while (pagesTraversed < 3 && (!selectedProduct || !selectedVariant)) {
      const pageRes = getCatalogPage(sessionCookie, currentCsrf, pageUrl);
      recordBusinessResponse(pageRes, false, false);
      if (pageRes.status !== 200) {
        break;
      }
      const product = getProductFromPage(pageRes.body);
      if (product && product.variants && product.variants.length > 0) {
        selectedProduct = product;
        selectedVariant = product.variants[0];
        break;
      }
      const next = getNextFromJson(pageRes.body);
      if (next) {
        pageUrl = next;
      } else {
        break;
      }
      pagesTraversed++;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    return false;
  }

  // Step: Get challenge form
  const challengeFormRes = getChallengeForm(sessionCookie, currentCsrf);
  recordBusinessResponse(challengeFormRes, false, false);
  check(challengeFormRes, {
    'challenge form returns 200': (r) => r.status === 200,
  });

  if (challengeFormRes.status === 200) {
    const challengeValue = getChallengeFromForm(challengeFormRes.body);
    const challengeAction = getFormAction(challengeFormRes.body);
    if (challengeValue && challengeAction) {
      const challengeRes = postChallenge(sessionCookie, currentCsrf, challengeValue, challengeAction);
      recordBusinessResponse(challengeRes, false, false);
      if (challengeRes.status === 302) {
        const location = getLocationFromHeaders(challengeRes.headers);
        if (location) {
          const grantUrl = location.startsWith('http') ? location : `${BASE_URL}${location}`;
          const grantRes = makeRequest('GET', grantUrl, { headers: sessionCookie ? { Cookie: sessionCookie } : {} }, null);
          recordBusinessResponse(grantRes, false, false);
          if (grantRes.status === 200) {
            grantId = getGrantIdFromJson(grantRes.body);
            const grantCsrf = getCsrfFromJson(grantRes.body);
            if (grantCsrf) currentCsrf = grantCsrf;
          }
        }
      } else if (challengeRes.status === 200) {
        grantId = getGrantIdFromJson(challengeRes.body);
        const grantCsrf = getCsrfFromJson(challengeRes.body);
        if (grantCsrf) currentCsrf = grantCsrf;
      }
    }
  }

  // Step: Create cart
  let cartRes = createCart(sessionCookie, currentCsrf, selectedProduct.id, selectedVariant.id, grantId);
  recordBusinessResponse(cartRes, false, false);

  // Handle 401 expired
  if (cartRes.status === 401 && getErrorFromJson(cartRes.body) === 'expired') {
    const retryResult = handle401Expired(sessionCookie, currentCsrf, null, (newSession, newCsrf) => {
