  const csrf = getCsrfFromForm(formRes.body);
  const loginNonce = getLoginNonceFromForm(formRes.body);
  if (!csrf || !loginNonce) {
    return { ok: false, error: 'missing csrf or login_nonce' };
  }

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password, csrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
    }
  );

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (!location) {
      return { ok: false, error: '302 without Location' };
    }
    const followRes = http.get(location, { redirects: 0 });
    if (followRes.status !== 200 && followRes.status !== 302) {
