    // Try to get csrf from login response body
    const loginCsrf = getCsrfFromForm(loginRes.body);
    if (loginCsrf) {
      return { ok: true, csrf: loginCsrf };
    }
    return { ok: false, error: 'no csrf after 302 follow' };
  }

  if (loginRes.status === 200) {
    try {
      const body = JSON.parse(loginRes.body);
      if (body.csrf) {
        return { ok: true, csrf: body.csrf };
      }
    } catch (e) {
      // ignore
    }
    const bodyCsrf = getCsrfFromForm(loginRes.body);
    if (bodyCsrf) {
      return { ok: true, csrf: bodyCsrf };
    }
    return { ok: false, error: 'no csrf in 200 login response' };
  }

  return { ok: false, error: `login status ${loginRes.status}` };
}

