import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const businessFailure = new Rate('business_failure');

const PROFILES = [
  { job_polls: 2, poll_interval: 0.02 },
  { job_polls: 3, poll_interval: 0.02, html_layout: 1, reverse_catalog: true }
];

const NEGATIVE_OVERRIDES = [{ job_fails: true }];

export const options = {
  scenarios: {
    reservation_scenario: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
};

function getProfile(vuIndex) {
  const profile = PROFILES[(vuIndex - 1) % PROFILES.length];
  const override = NEGATIVE_OVERRIDES[(vuIndex - 1) % NEGATIVE_OVERRIDES.length];
  return Object.assign({}, profile, override);
}

function extractCsrf(html) {
  const match = html.match(/name="csrf"[^>]*value="([^"]+)"/);
  if (match) return match[1];
  const match2 = html.match(/name=['"]csrf['"][^>]*value=['"]([^'"]+)['"]/);
  if (match2) return match2[1];
  const match3 = html.match(/value="([^"]+)"[^>]*name="csrf"/);
  if (match3) return match3[1];
  return null;
}

function login(httpClient, username, password) {
  // GET login form
  const formRes = httpClient.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
  });
  check(formRes, {
    'login form status 200': (r) => r.status === 200,
  });
  const csrf = extractCsrf(formRes.body);
  check(csrf, {
    'csrf extracted from login form': (c) => c !== null && c.length > 0,
  });

  // POST login
  const loginRes = httpClient.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf,
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });

  let loginCsrf = csrf;
  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    check(location, {
      'login 302 has Location': (l) => l !== undefined && l !== null,
    });
    const followRes = httpClient.get(location, { redirects: 0 });
    check(followRes, {
      'login follow status 200': (r) => r.status === 200,
    });
    const body = followRes.body;
    try {
      const json = JSON.parse(body);
      if (json.csrf) loginCsrf = json.csrf;
    } catch (e) {
      // not JSON, try HTML
      const extracted = extractCsrf(body);
      if (extracted) loginCsrf = extracted;
    }
  } else if (loginRes.status === 200) {
    try {
      const json = JSON.parse(loginRes.body);
      if (json.csrf) loginCsrf = json.csrf;
    } catch (e) {
      const extracted = extractCsrf(loginRes.body);
      if (extracted) loginCsrf = extracted;
    }
  }

  check(loginRes, {
    'login status 200 or 302': (r) => r.status === 200 || r.status === 302,
  });

  return loginCsrf;
}

function getCatalog(httpClient, csrf, reverse) {
  const catalogRes = httpClient.get(`${BASE_URL}/v2/catalog`, {
    headers: { 'X-CSRF-Token': csrf },
  });
  check(catalogRes, {
    'catalog status 200': (r) => r.status === 200,
  });
  let products = [];
  try {
    const json = JSON.parse(catalogRes.body);
    if (json.data && json.data.products) {
      products = json.data.products;
    }
  } catch (e) {
    // ignore
  }
  if (reverse) {
    products = products.slice().reverse();
  }
  return products;
}

function getCatalogPage(httpClient, csrf, pageUrl) {
  const res = httpClient.get(`${BASE_URL}${pageUrl}`, {
    headers: { 'X-CSRF-Token': csrf },
  });
  check(res, {
    'catalog page status 200': (r) => r.status === 200,
  });
  let product = null;
  let next = null;
  try {
    const json = JSON.parse(res.body);
    if (json.data && json.data.products && json.data.products.length > 0) {
      product = json.data.products[0];
    }
    next = json.next || null;
  } catch (e) {
    // ignore
  }
  return { product, next };
}

function createCart(httpClient, csrf, productId, variantId, grantId) {
  const payload = {
    product_id: productId,
    variant_id: variantId,
  };
  if (grantId) {
    payload.grant_id = grantId;
  }
  const res = httpClient.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  check(res, {
    'cart creation status 201': (r) => r.status === 201,
  });
  let cartId = null;
  let newCsrf = csrf;
  let etag = null;
  try {
    const json = JSON.parse(res.body);
    cartId = json.id;
    if (json.csrf) newCsrf = json.csrf;
  } catch (e) {
    // ignore
  }
  etag = res.headers['ETag'] || res.headers['Etag'] || res.headers['etag'];
  return { cartId, csrf: newCsrf, etag };
}

function getCart(httpClient, csrf, cartId) {
  const res = httpClient.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: { 'X-CSRF-Token': csrf },
  });
  check(res, {
    'get cart status 200': (r) => r.status === 200,
  });
  const etag = res.headers['ETag'] || res.headers['Etag'] || res.headers['etag'];
  return { etag, csrf };
}

function patchCart(httpClient, csrf, cartId, quantity, etag) {
  const res = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
    quantity: quantity,
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
    },
  });
  let newCsrf = csrf;
  let newEtag = etag;
  if (res.status === 412) {
    // re-read and retry once
    const reRead = getCart(httpClient, csrf, cartId);
    newEtag = reRead.etag;
    newCsrf = reRead.csrf;
    const retryRes = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
      quantity: quantity,
    }), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': newCsrf,
        'If-Match': newEtag,
      },
    });
    check(retryRes, {
      'patch cart retry status 200': (r) => r.status === 200,
    });
    try {
      const json = JSON.parse(retryRes.body);
      if (json.csrf) newCsrf = json.csrf;
    } catch (e) {
      // ignore
    }
    newEtag = retryRes.headers['ETag'] || retryRes.headers['Etag'] || retryRes.headers['etag'];
    return { csrf: newCsrf, etag: newEtag };
  }
  check(res, {
    'patch cart status 200': (r) => r.status === 200,
  });
  try {
    const json = JSON.parse(res.body);
    if (json.csrf) newCsrf = json.csrf;
  } catch (e) {
    // ignore
  }
  newEtag = res.headers['ETag'] || res.headers['Etag'] || res.headers['etag'];
  return { csrf: newCsrf, etag: newEtag };
}

function createReservation(httpClient, csrf, cartId) {
  const res = httpClient.post(`${BASE_URL}/v2/reservations`, JSON.stringify({
    cart_id: cartId,
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  check(res, {
    'reservation creation status 202': (r) => r.status === 202,
  });
  let statusUrl = null;
  let newCsrf = csrf;
  try {
    const json = JSON.parse(res.body);
    statusUrl = json.status_url;
    if (json.csrf) newCsrf = json.csrf;
  } catch (e) {
    // ignore
  }
  return { statusUrl, csrf: newCsrf };
}

function pollReservation(httpClient, csrf, statusUrl, maxPolls, pollInterval, jobFails) {
  let reservationId = null;
  let finalCsrf = csrf;
  let polls = 0;
  let status = 'pending';

  for (let i = 0; i < maxPolls; i++) {
    polls++;
    sleep(pollInterval);
    const res = httpClient.get(statusUrl, {
      headers: { 'X-CSRF-Token': finalCsrf },
    });
    check(res, {
      'poll status 200': (r) => r.status === 200,
    });
    try {
      const json = JSON.parse(res.body);
      status = json.status;
      if (json.csrf) finalCsrf = json.csrf;
      if (status === 'ready' && json.reservation_id) {
        reservationId = json.reservation_id;
        break;
      }
      if (status === 'failed') {
        break;
      }
    } catch (e) {
      // ignore
    }
  }

  if (jobFails) {
    // Negative control: force failure by not returning reservation_id
    return { reservationId: null, csrf: finalCsrf, status, polls };
  }

  return { reservationId, csrf: finalCsrf, status, polls };
}

