      const followResponse = http.get(`${BASE_URL}${location}`, {
        headers: {
          'X-CSRF-Token': csrf,
        },
        tags: { name: 'challenge-follow' },
      });

      businessResponses.add(1);

      if (followResponse.status === 200) {
        const grantId = extractGrantId(followResponse.body);
        const newCsrf = extractCsrfFromJson(followResponse.body);
        return {
          grantId: grantId,
          csrf: newCsrf || csrf,
          response: followResponse,
        };
      }
    }
  }

  return null;
}

// Helper: perform work
function performWork(csrf) {
  let response = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    tags: { name: 'work' },
  });

  businessResponses.add(1);

  let retries = 0;
  while (isScheduled429(response) && retries < 4) {
    sleep(1); // Retry-After 1s
    response = http.post(`${BASE_URL}/v2/work`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
      tags: { name: 'work-retry' },
    });
    businessResponses.add(1);
    retries++;
  }

  if (response.status === 200) {
    const data = JSON.parse(response.body);
    if (data.ok === true) {
      return true;
    }
  }

  if (response.status === 500) {
    unexpectedFailures.add(1);
  }

  return false;
}

// Helper: handle 401 recovery for an operation
function handle401Recovery(response, cartId, currentCsrf, operationFn) {
  if (isExpired(response)) {
    // Session expired - renew
    const renewResult = renewSession(currentCsrf);
    if (renewResult) {
      // Recover cart if exists
      if (cartId) {
        const recoverResult = recoverCart(cartId, renewResult.csrf);
        if (recoverResult) {
          return {
            csrf: recoverResult.csrf,
            recovered: true,
          };
        }
      }
      return {
        csrf: renewResult.csrf,
        recovered: true,
      };
    }
  } else if (isSessionRevoked(response)) {
    // Session revoked - need fresh login
    const loginResult = performLogin('bench', 'bench');
    if (loginResult) {
      // Recover cart
      if (cartId) {
        const recoverResult = recoverCart(cartId, loginResult.csrf);
        if (recoverResult) {
          return {
            csrf: recoverResult.csrf,
            recovered: true,
            freshLogin: true,
          };
        }
      }
      return {
        csrf: loginResult.csrf,
        recovered: true,
        freshLogin: true,
      };
    }
  } else if (isDenied(response)) {
    // Denied - fail assertion
    unexpectedFailures.add(1);
    return null;
  }

  return null;
}

// Main journey function
function journey(userIndex, iterationIndex) {
  const account = accounts[userIndex % accounts.length];
  const username = account.username;
  const password = account.password;

  // Get per-thread delay from CSV
  let delay = 0;
  if (userIndex === 0) {
    delay = account1Delays[iterationIndex % account1Delays.length] || 0;
  } else {
    delay = account2Delays[iterationIndex % account2Delays.length] || 0;
  }

  // Apply CSV delay to stagger subsequent work
  if (delay > 0) {
    sleep(delay / 1000);
  }

  // Initial login
  let session = performLogin(username, password);
  if (!session) {
    unexpectedFailures.add(1);
    return;
  }

  let csrf = session.csrf;
  let cartId = null;
  let cartEtag = null;
  let orderCommitted = false;
  let recoveryAttempts = 0;
  const maxRecoveryAttempts = 3;

  // Get catalog
  const products = getCatalog();
  if (products.length === 0) {
    unexpectedFailures.add(1);
    return;
  }

  // Select first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;

  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    // Try catalog pages
    let pageUrl = '/v2/catalog/page';
    let pagesTraversed = 0;

    while (pagesTraversed < 3 && !selectedProduct) {
      const pageResult = getCatalogPage(pageUrl);
      if (pageResult && pageResult.product) {
        const product = pageResult.product;
        if (product.variants && product.variants.length > 0) {
          for (const variant of product.variants) {
            if (variant.in_stock) {
              selectedProduct = product;
              selectedVariant = variant;
              break;
            }
          }
        }
        if (!selectedProduct && pageResult.next) {
          pageUrl = pageResult.next;
          pagesTraversed++;
        } else {
          break;
        }
      } else {
        break;
      }
    }
  }

  if (!selectedProduct || !selectedVariant) {
    unexpectedFailures.add(1);
    return;
  }

  // Try to get challenge for grant_id
  let grantId = null;
  const challengeForm = getChallengeForm(csrf);
  if (challengeForm && challengeForm.action && challengeForm.inputName) {
    const challengeResult = postChallenge(challengeForm.action, 'bench', csrf);
    if (challengeResult && challengeResult.grantId) {
      grantId = challengeResult.grantId;
      csrf = challengeResult.csrf;
    }
  }

  // Create cart
  let cartResult = createCart(selectedProduct.id, selectedVariant.id, grantId, csrf);
  if (!cartResult) {
    unexpectedFailures.add(1);
    return;
  }

  cartId = cartResult.cartId;
  cartEtag = cartResult.etag;
  csrf = cartResult.csrf;

  // Patch cart to quantity 1
  const patchResult = patchCart(cartId, 1, cartEtag, csrf);
  if (patchResult) {
    cartEtag = patchResult.etag;
    csrf = patchResult.csrf;
  } else {
    // Check if 401
    const cartData = getCart(cartId, csrf);
    if (cartData) {
      cartEtag = cartData.etag;
    }
  }

  // Create reservation
  let reservationId = null;
  const reservationResult = createReservation(cartId, csrf);
  if (reservationResult) {
    csrf = reservationResult.csrf;
    const pollResult = pollReservation(reservationResult.statusUrl, csrf);
    if (pollResult) {
      reservationId = pollResult.reservationId;
      csrf = pollResult.csrf;
    }
  }

  // Create order with idempotency key
  const idempotencyKey = `order-${userIndex}-${iterationIndex}-${Date.now()}`;
  let orderResult = createOrder(cartId, reservationId, idempotencyKey, cartEtag, csrf);

  if (orderResult && orderResult.accepted === true) {
    orderCommitted = true;
    csrf = orderResult.csrf;
  } else if (orderResult && orderResult.accepted === false) {
    // Business failure - not success
    businessFailures.add(1);
    return;
  } else {
    // Check if 401
    const lastResponse = orderResult ? orderResult.response : null;
    if (lastResponse && (isExpired(lastResponse) || isSessionRevoked(lastResponse))) {
      // Attempt recovery
      const recoveryResult = handle401Recovery(lastResponse, cartId, csrf, null);
      if (recoveryResult) {
        csrf = recoveryResult.csrf;
        recoveryAttempts++;

        // Retry order once
        const retryOrderResult = createOrder(cartId, reservationId, idempotencyKey, cartEtag, csrf);
        if (retryOrderResult && retryOrderResult.accepted === true) {
          orderCommitted = true;
          csrf = retryOrderResult.csrf;
        } else if (retryOrderResult && retryOrderResult.accepted === false) {
          businessFailures.add(1);
          return;
        }
      }
    }
  }

  // Perform work
  performWork(csrf);

  if (!orderCommitted) {
    unexpectedFailures.add(1);
  }
}

// Export options
export const options = {
  scenarios: {
    ownership: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 1,
      maxDuration: '5m',
    },
  },
  thresholds: {
    business_failures: ['count<100'],
    unexpected_failures: ['count<100'],
  },
};

// Main function
export default function () {
  const vuId = __VU - 1; // 0-based
  const iterationIndex = __ITER;

  journey(vuId, iterationIndex);

  // Synchronization point after initial logins
  // Both users deliberately share account bench
  // The second login invalidates the first session
  // This is detected during the journey and recovered
