function extractCsrfFromHtml(html) {
  const regex = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/;
  const match = html.match(regex);
  return match ? match[1] : null;
}

function extractLocation(headers) {
  const loc = headers['Location'];
  return loc || null;
}

function extractEtag(headers) {
  const etag = headers['ETag'];
  return etag || null;
}

function extractError(body) {
  const match = body.match(/"error"\s*:\s*"(expired|session|denied)"/);
  return match ? match[1] : null;
}

function handleExpiry(response, state, operationFn, cartId) {
  const error = extractError(response.body);
  if (error === 'expired') {
    const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
    });
    if (renewRes.status === 200) {
      try {
        const renewBody = renewRes.json();
        if (renewBody.csrf) state.csrf = renewBody.csrf;
      } catch (e) {}
      if (cartId) {
        http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrf,
          },
        });
      }
      return operationFn();
    }
  } else if (error === 'session') {
    const formRes = http.get(`${BASE_URL}/v2/login-form`);
    const formCsrf = extractCsrfFromHtml(formRes.body);
    if (formCsrf) state.csrf = formCsrf;
    const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
      username: state.username,
      password: 'bench',
      csrf: state.csrf,
    }), {
      headers: { 'Content-Type': 'application/json' },
    });
    if (loginRes.status === 302) {
      const loc = extractLocation(loginRes.headers);
      if (loc) {
        http.get(loc.startsWith('http') ? loc : `${BASE_URL}${loc}`);
      }
    } else if (loginRes.status === 200) {
      try {
        const loginBody = loginRes.json();
        if (loginBody.csrf) state.csrf = loginBody.csrf;
      } catch (e) {}
    }
    if (cartId) {
      http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
        },
      });
    }
    return operationFn();
  }
  return response;
}

function login(state) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`);
  check(formRes, { 'login form status 200': (r) => r.status === 200 });
  const formCsrf = extractCsrfFromHtml(formRes.body);
  if (formCsrf) state.csrf = formCsrf;

  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: state.username,
    password: 'bench',
    csrf: state.csrf,
  }), {
    headers: { 'Content-Type': 'application/json' },
  });

  if (loginRes.status === 302) {
    const loc = extractLocation(loginRes.headers);
    if (loc) {
      const redirectRes = http.get(loc.startsWith('http') ? loc : `${BASE_URL}${loc}`);
      try {
        const redirectBody = redirectRes.json();
        if (redirectBody.csrf) state.csrf = redirectBody.csrf;
        if (redirectBody.grant_id) state.grant = redirectBody.grant_id;
      } catch (e) {}
    }
  } else if (loginRes.status === 200) {
    try {
      const loginBody = loginRes.json();
      if (loginBody.csrf) state.csrf = loginBody.csrf;
    } catch (e) {}
  }
  check(loginRes, { 'login response has csrf': (r) => r.body.includes('"csrf"') });
}

function getCatalog(state) {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`);
  check(catalogRes, { 'catalog status 200': (r) => r.status === 200 });
  try {
    const catalogBody = catalogRes.json();
    if (catalogBody.csrf) state.csrf = catalogBody.csrf;
    const products = catalogBody.data && catalogBody.data.products ? catalogBody.data.products : [];
    for (const product of products) {
      if (product.variants && product.variants.length > 0 && product.variants[0].in_stock === true) {
        state.product = product.id;
        state.variant = product.variants[0].id;
        break;
      }
    }
  } catch (e) {}
}

function createCart(state) {
  const payload = {
    product_id: state.product,
    variant_id: state.variant,
  };
  if (state.grant && state.grant !== 'MISSING') {
    payload.grant_id = state.grant;
  }
  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
  });
  if (cartRes.status === 401) {
    const error = extractError(cartRes.body);
    if (error === 'expired' || error === 'session') {
      return handleExpiry(cartRes, state, () => createCart(state), null);
    }
  }
  check(cartRes, { 'cart created': (r) => r.status === 201 && r.body.includes('"id"') });
  try {
    const cartBody = cartRes.json();
    if (cartBody.csrf) state.csrf = cartBody.csrf;
    if (cartBody.id) state.cart = cartBody.id;
  } catch (e) {}
  const etag = extractEtag(cartRes.headers);
  if (etag) state.etag = etag;
  if (cartRes.body.includes('"id"')) state.hasCart = true;
}

function createOrder(state) {
  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify({
    cart_id: state.cart,
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Idempotency-Key': state.cart,
    },
  });
  if (orderRes.status === 401) {
    const error = extractError(orderRes.body);
    if (error === 'expired' || error === 'session') {
      return handleExpiry(orderRes, state, () => createOrder(state), state.cart);
    }
  }
  check(orderRes, { 'order accepted': (r) => r.status === 201 && r.body.includes('"accepted"') && r.body.includes('true') });
  try {
    const orderBody = orderRes.json();
    if (orderBody.csrf) state.csrf = orderBody.csrf;
  } catch (e) {}
}

export default function () {
  const threadNum = (__VU - 1) % 16 + 1;
  const state = {
    username: `bench-${threadNum}`,
