    checkoutStarts.add(1);
    if (retryRes.status === 201) {
      try {
        const body = retryRes.json();
        if (body && body.accepted === true) {
          state.checkoutCommitted = true;
          extractCsrf(retryRes);
          return true;
        }
      } catch (e) {}
    }
  }

  businessFailures.add(1);
  return false;
}

function runJourney() {
  state.csrf = 'MISSING';
  state.cart = 'MISSING';
  state.etag = 'MISSING';
  state.hasCart = false;
  state.grant = 'MISSING';
  state.product = 'MISSING';
  state.variant = 'MISSING';
  state.checkoutCommitted = false;
  state.idempotencyKey = null;

  freshLogin();
  selectProduct();
  createCart();
  checkout();
}

