    return { product, next };
  } catch (e) {
    return null;
  }
}

// Helper to get challenge form
function getChallengeForm(csrf) {
  const res = http.get(`${BASE_URL}/v2/challenge-form`, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  if (res.status !== 200) return null;
  const actionMatch = res.body.match(/<form[^>]*\baction=["']([^"']+)["'][^>]*>/i);
  const challengeMatch = res.body.match(/<input[^>]*\bname=["']challenge["'][^>]*>/i);
  if (!actionMatch || !challengeMatch) return null;
  return { action: actionMatch[1], hasChallenge: true };
