import http from 'k6/http';
import { check, sleep } from 'k6';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {},
};

function parseJson(res) {
  try {
    return res.json();
  } catch (e) {
    return {};
  }
}

function extractCsrf(body, current) {
  const m = body.match(/"csrf"\s*:\s*"([^"]+)"/);
  return m ? m[1] : current;
}

function extractGrantId(body, current) {
  const m = body.match(/"grant_id"\s*:\s*"([^"]+)"/);
  return m ? m[1] : current;
}

function extractCartId(body, current) {
  const m = body.match(/"id"\s*:\s*"(cart-[^"]+)"/);
  return m ? m[1] : current;
}

function extractEtag(headers, current) {
  const etag = headers['ETag'] || headers['Etag'] || headers['etag'];
  return etag || current;
}

function extractLocation(headers, current) {
  const loc = headers['Location'] || headers['location'];
  return loc || current;
}

function hasLocation(headers) {
  return !!(headers['Location'] || headers['location']);
}

function extractFormCsrf(body, current) {
  const m = body.match(/<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  return m ? m[1] : current;
}

function isExpiryError(body) {
  return /"error"\s*:\s*"(?:expired|session)"/.test(body);
}

function isDeniedError(body) {
  return /"error"\s*:\s*"denied"/.test(body);
}

function buildHeaders(csrf, etag, cart) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };
  if (etag && etag !== 'MISSING') headers['If-Match'] = etag;
  if (cart && cart !== 'MISSING') headers['Idempotency-Key'] = cart;
  return headers;
}

function loginForm(state) {
  const res = http.get(`${BASE_URL}/v2/login-form`, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  state.form = extractFormCsrf(res.body, state.form);
  return res;
}

function login(state, username) {
  const payload = JSON.stringify({ username, password: 'bench', csrf: state.form });
  const res = http.post(`${BASE_URL}/v2/login`, payload, {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
    redirects: 0,
  });
  state.csrf = extractCsrf(res.body, state.csrf);
  state.location = extractLocation(res.headers, state.location);
  state.redirect = hasLocation(res.headers);
  return res;
}

function followRedirect(state) {
  const res = http.get(`${BASE_URL}${state.location}`, {
    headers: buildHeaders(state.csrf, state.etag, state.cart),
    redirects: 0,
  });
  state.csrf = extractCsrf(res.body, state.csrf);
  state.grant = extractGrantId(res.body, state.grant);
  return res;
}

function getCatalog(state) {
  const res = http.get(`${BASE_URL}/v2/catalog`, {
    headers: buildHeaders(state.csrf, state.etag, state.cart),
    redirects: 0,
  });
  const body = parseJson(res);
  const products = (body.data && body.data.products) || [];
  for (const p of products) {
    if (p.variants && p.variants[0] && p.variants[0].in_stock === true) {
      state.product = p.id;
      state.variant = p.variants[0].id;
      break;
    }
  }
  return res;
}

function createCart(state) {
  const payload = JSON.stringify({
    product_id: state.product,
    variant_id: state.variant,
    grant_id: state.grant,
  });
  const res = http.post(`${BASE_URL}/v2/carts`, payload, {
    headers: buildHeaders(state.csrf, state.etag, state.cart),
    redirects: 0,
  });
  state.csrf = extractCsrf(res.body, state.csrf);
  state.cart = extractCartId(res.body, state.cart);
  state.etag = extractEtag(res.headers, state.etag);
  if (/"id"\s*:\s*"cart-/.test(res.body)) state.hasCart = true;
  return res;
}

function postOrder(state) {
  const payload = JSON.stringify({ cart_id: state.cart });
  const res = http.post(`${BASE_URL}/v2/orders`, payload, {
    headers: buildHeaders(state.csrf, state.etag, state.cart),
    redirects: 0,
  });
  state.csrf = extractCsrf(res.body, state.csrf);
  state.etag = extractEtag(res.headers, state.etag);
  return res;
}

function renewSession(state) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: buildHeaders(state.csrf, state.etag, state.cart),
    redirects: 0,
  });
  state.csrf = extractCsrf(res.body, state.csrf);
  state.etag = extractEtag(res.headers, state.etag);
  return res;
}

function freshLogin(state, username) {
  loginForm(state);
  const res = login(state, username);
  if (state.redirect) {
    followRedirect(state);
  }
  return res;
}

function recoverCart(state) {
  const res = http.post(`${BASE_URL}/v2/carts/${state.cart}/recover`, '{}', {
    headers: buildHeaders(state.csrf, state.etag, state.cart),
    redirects: 0,
  });
  state.csrf = extractCsrf(res.body, state.csrf);
  state.etag = extractEtag(res.headers, state.etag);
  return res;
}

function handleExpiry(state, username, interruptedOp) {
  // Renew session
  const renewRes = renewSession(state);
  if (isExpiryError(renewRes.body)) {
    // Session revoked: fresh login
    freshLogin(state, username);
  }
  // Recover cart if exists
  if (state.hasCart) {
    recoverCart(state);
  }
  // Retry interrupted operation once
  return interruptedOp(state);
}

export default function () {
  const vuId = __VU;
  const username = `bench-${vuId}`;

  const state = {
    csrf: 'MISSING',
    form: 'MISSING',
    cart: 'MISSING',
    etag: 'MISSING',
    hasCart: false,
    grant: 'MISSING',
    product: 'MISSING',
    variant: 'MISSING',
    location: 'MISSING',
    redirect: false,
  };

  // Fresh login
  loginForm(state);
  let res = login(state, username);
  check(res, { 'login has csrf': (r) => /"csrf"\s*:/.test(r.body) });
  if (state.redirect) {
    followRedirect(state);
  }

  // Catalog
  res = getCatalog(state);
  check(res, { 'catalog ok': (r) => r.status === 200 });

  // Create cart
  res = createCart(state);
  check(res, { 'cart created': (r) => /"id"\s*:\s*"cart-/.test(r.body) });

  // Order
  res = postOrder(state);
  check(res, { 'order accepted': (r) => /"accepted"\s*:\s*true/.test(r.body) });

  // Expiry recovery branch
  if (isExpiryError(res.body)) {
    const retryRes = handleExpiry(state, username, postOrder);
    check(retryRes, { 'order accepted after recovery': (r) => /"accepted"\s*:\s*true/.test(r.body) });
  }

  sleep(0.1);
}
