function getCsrfFromForm(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  return match ? match[1] : null;
}

function login(httpClient, username, password) {
  const formRes = httpClient.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });
  if (formRes.status !== 200) return null;

  const csrf = getCsrfFromForm(formRes.body);
  if (!csrf) return null;

  const loginRes = httpClient.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (location) {
      const followRes = httpClient.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        redirects: 0,
        tags: { name: 'login_redirect' }
      });
      if (followRes.status !== 200) return null;
      try {
        const data = followRes.json();
        return data.csrf || null;
      } catch (e) {
        return null;
      }
    }
    return null;
  }

  if (loginRes.status !== 200) return null;
  try {
    const data = loginRes.json();
    return data.csrf || null;
  } catch (e) {
    return null;
  }
}

function renewSession(httpClient, csrf) {
  const res = httpClient.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'session_renew' }
