    t0 = Date.now();
    workCount = 0;
    currentFixture = randomItem(FIXTURE_VARIANTS);
    return;
  }

  // Check if we're in scored period
  const elapsed = now - t0;

  if (elapsed < WARMUP_SECONDS * 1000) {
