    const cartInfo = getCart(cartId, csrf);
    if (cartInfo) {
      const res2 = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
        quantity: quantity
      }), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
          'If-Match': cartInfo.etag
        },
        tags: { name: 'cart_patch_retry' }
      });

      if (res2.status === 200) {
        try {
          const body = JSON.parse(res2.body);
          return {
            csrf: body.csrf || csrf,
            etag: res2.headers['ETag'] || cartInfo.etag
          };
        } catch (e) {
          return { csrf: csrf, etag: cartInfo.etag };
        }
      }
    }
    return null;
  }

  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      return {
        csrf: body.csrf || csrf,
        etag: res.headers['ETag'] || etag
