        // Session revoked, re-login
        const newCsrf = login('bench', 'bench');
        if (newCsrf) {
          const retryRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
            headers: {
              'Content-Type': 'application/json',
              'X-CSRF-Token': newCsrf
            },
            tags: { name: 'work_retry_after_relogin' }
          });

          if (retryRes.status === 200) {
            try {
