function fullJourney(userIndex) {
  const username = `bench-${userIndex}`;
  const password = 'bench';

  // Login
  let csrf = login(username, password);
  if (!csrf) {
    return;
  }

  // Get catalog
  const products = getCatalog(csrf);
  if (products.length === 0) {
    return;
  }

  // Select first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;

  for (const product of products) {
    for (const variant of product.variants) {
      if (variant.in_stock) {
        selectedProduct = product;
        selectedVariant = variant;
        break;
      }
    }
    if (selectedProduct) break;
  }

  if (!selectedProduct) {
    return;
  }

  // Try to get grant_id from challenge
  let grantId = null;
  const challengeAction = getChallengeForm(csrf);
  if (challengeAction) {
    const challengeResult = postChallenge(challengeAction, csrf);
    if (challengeResult) {
      grantId = challengeResult.grantId;
      csrf = challengeResult.csrf;
    }
  }

  // Create cart
  const cartResult = createCart(selectedProduct.id, selectedVariant.id, grantId, csrf);
  if (!cartResult) {
    return;
  }

  csrf = cartResult.csrf;
  let etag = cartResult.etag;
  const cartId = cartResult.cartId;

  // Patch cart
  const patchResult = patchCart(cartId, 1, etag, csrf);
  if (patchResult) {
    csrf = patchResult.csrf;
    etag = patchResult.etag;
  }

  // Create reservation
  let reservationId = null;
  const reservationResult = createReservation(cartId, csrf);
  if (reservationResult) {
    csrf = reservationResult.csrf;
    const pollResult = pollReservation(reservationResult.statusUrl, csrf);
    if (pollResult) {
      reservationId = pollResult.reservationId;
      csrf = pollResult.csrf;
    }
  }

  // Create order
  const idempotencyKey = `order-${cartId}-${Date.now()}`;
  const orderResult = createOrder(cartId, reservationId, idempotencyKey, etag, csrf);
  if (orderResult) {
    csrf = orderResult.csrf;
  }

  // Perform work
  const workResult = performWork(csrf);
  if (workResult.success) {
    csrf = workResult.csrf;
  }
}

