function getProfile(userIndex) {
  return profiles[userIndex % profiles.length];
}

function login(username, password) {
  const loginFormRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });

  if (loginFormRes.status !== 200) {
    return null;
  }

  const csrfMatch = loginFormRes.body.match(/name="csrf"[^>]*value="([^"]+)"/);
  if (!csrfMatch) {
    return null;
  }
  const csrf = csrfMatch[1];

  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (location) {
      const followRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        redirects: 0,
        tags: { name: 'login_follow' }
      });
      if (followRes.status === 200) {
        try {
          const body = JSON.parse(followRes.body);
          return { csrf: body.csrf, user: body.user };
        } catch (e) {
          return null;
        }
      }
    }
    return null;
  }

  if (loginRes.status === 200) {
    try {
      const body = JSON.parse(loginRes.body);
      return { csrf: body.csrf, user: body.user };
    } catch (e) {
      return null;
    }
  }

  return null;
}

function renewSession(currentCsrf) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf
    },
    redirects: 0,
    tags: { name: 'session_renew' }
  });

  if (renewRes.status === 200) {
    try {
      const body = JSON.parse(renewRes.body);
      return body.csrf || currentCsrf;
    } catch (e) {
      return currentCsrf;
    }
  }

  return null;
}

function getCatalog(profile) {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, {
    redirects: 0,
    tags: { name: 'catalog' }
  });

  if (catalogRes.status !== 200) {
    return null;
  }

  try {
    const body = JSON.parse(catalogRes.body);
    if (body.data && body.data.products && body.data.products.length > 0) {
      return body.data.products;
    }
  } catch (e) {
    return null;
  }

  return null;
}

function getCatalogPage(profile, pageUrl) {
  const url = pageUrl.startsWith('http') ? pageUrl : `${BASE_URL}${pageUrl}`;
  const pageRes = http.get(url, {
    redirects: 0,
    tags: { name: 'catalog_page' }
  });

  if (pageRes.status !== 200) {
    return null;
  }

  try {
    const body = JSON.parse(pageRes.body);
    return body;
  } catch (e) {
    return null;
  }
}

function createCart(csrf, productId, variantId, grantId) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };
  if (grantId) {
    payload.grant_id = grantId;
  }

  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'create_cart' }
  });

  if (cartRes.status === 201) {
    try {
      const body = JSON.parse(cartRes.body);
      return {
        id: body.id,
        csrf: body.csrf || csrf,
        etag: cartRes.headers['ETag'] || cartRes.headers['Etag'] || null
      };
    } catch (e) {
      return null;
    }
  }

  return null;
}

function getCart(cartId, csrf) {
  const cartRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: {
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'get_cart' }
  });

  if (cartRes.status === 200) {
    return {
      etag: cartRes.headers['ETag'] || cartRes.headers['Etag'] || null,
      csrf: csrf
    };
  }

  return null;
}

function patchCart(cartId, csrf, etag, quantity) {
  const patchRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
    quantity: quantity
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    redirects: 0,
    tags: { name: 'patch_cart' }
  });

  if (patchRes.status === 200) {
    try {
      const body = JSON.parse(patchRes.body);
      return {
        csrf: body.csrf || csrf,
        etag: patchRes.headers['ETag'] || patchRes.headers['Etag'] || etag
      };
    } catch (e) {
      return {
        csrf: csrf,
        etag: patchRes.headers['ETag'] || patchRes.headers['Etag'] || etag
      };
    }
  }

  if (patchRes.status === 412) {
    return { conflict: true };
  }

  return null;
}

function createOrder(cartId, csrf, etag, reservationId, idempotencyKey) {
  const payload = {
    cart_id: cartId,
    Idempotency-Key: idempotencyKey
  };
  if (reservationId) {
    payload.reservation_id = reservationId;
  }

  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    redirects: 0,
    tags: { name: 'create_order' }
  });

  if (orderRes.status === 201) {
    try {
      const body = JSON.parse(orderRes.body);
      if (body.accepted === true) {
        return {
          accepted: true,
          id: body.id,
          csrf: body.csrf || csrf
        };
      }
      return { accepted: false };
    } catch (e) {
      return null;
    }
  }

  if (orderRes.status === 200) {
    try {
      const body = JSON.parse(orderRes.body);
      if (body.accepted === false) {
        return { accepted: false };
      }
    } catch (e) {
      return null;
    }
  }

  return null;
}

function getChallengeForm(csrf) {
  const challengeRes = http.get(`${BASE_URL}/v2/challenge-form`, {
    headers: {
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'challenge_form' }
  });

  if (challengeRes.status !== 200) {
    return null;
  }

  const actionMatch = challengeRes.body.match(/action="([^"]+)"/);
  const challengeMatch = challengeRes.body.match(/name="challenge"[^>]*value="([^"]+)"/);

  if (!actionMatch || !challengeMatch) {
    return null;
  }

  return {
    action: actionMatch[1],
    challenge: challengeMatch[1]
  };
}

function postChallenge(action, challenge, csrf) {
  const actionUrl = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const challengeRes = http.post(actionUrl, JSON.stringify({
    challenge: challenge
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'post_challenge' }
  });

  if (challengeRes.status === 302) {
    const location = challengeRes.headers['Location'];
    if (location) {
      const followRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        redirects: 0,
        tags: { name: 'challenge_follow' }
      });
      if (followRes.status === 200) {
        try {
          const body = JSON.parse(followRes.body);
          return {
            grant_id: body.grant_id,
            csrf: body.csrf || csrf
          };
        } catch (e) {
          return null;
        }
      }
    }
  }

  return null;
}

function createReservation(cartId, csrf) {
  const resRes = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({
    cart_id: cartId
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'create_reservation' }
  });

  if (resRes.status === 202) {
    try {
      const body = JSON.parse(resRes.body);
      return {
        status_url: body.status_url,
        csrf: body.csrf || csrf
      };
    } catch (e) {
      return null;
    }
  }

  return null;
}

function pollReservation(statusUrl, csrf) {
  const url = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;

  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      sleep(0.05);
    }

    const pollRes = http.get(url, {
      headers: {
        'X-CSRF-Token': csrf
      },
      redirects: 0,
      tags: { name: 'poll_reservation' }
    });

    if (pollRes.status === 200) {
      try {
        const body = JSON.parse(pollRes.body);
        if (body.status === 'ready' && body.reservation_id) {
          return {
            reservation_id: body.reservation_id,
            csrf: body.csrf || csrf
          };
        }
        if (body.status === 'failed') {
          return null;
        }
      } catch (e) {
        return null;
      }
    }
  }

  return null;
}

function recoverCart(cartId, csrf) {
  const recoverRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'recover_cart' }
  });

  if (recoverRes.status === 200) {
    try {
      const body = JSON.parse(recoverRes.body);
      return body.csrf || csrf;
    } catch (e) {
      return csrf;
    }
  }

  return csrf;
}

function doWork(csrf) {
  const startTime = Date.now();

  const workRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'work' }
  });

  workBusinessResponses++;

  if (workRes.status === 200) {
    try {
      const body = JSON.parse(workRes.body);
      if (body.ok === true) {
        workSuccessCount.add(1);
        workStartTrend.add(startTime);
        workStartTimes.push(startTime);
        workCompletions.push(Date.now());
        return { success: true, csrf: body.csrf || csrf };
      }
    } catch (e) {
      // fall through
    }
    workUnexpectedFailures++;
    unexpectedErrorRate.add(1);
    workUnexpectedErrors.push(Date.now());
    return { success: false, csrf: csrf };
  }

  if (workRes.status === 429) {
    workScheduled429.push(Date.now());
    const retryAfter = workRes.headers['Retry-After'];
    const waitSeconds = retryAfter ? parseInt(retryAfter) : retryAfterSeconds;
    return { scheduled429: true, retryAfter: waitSeconds, csrf: csrf };
  }

  if (workRes.status === 401) {
    try {
      const body = JSON.parse(workRes.body);
      if (body.error === 'expired') {
        return { expired: true, csrf: csrf };
      }
      if (body.error === 'session') {
        return { sessionRevoked: true, csrf: csrf };
      }
      if (body.error === 'denied') {
        workUnexpectedFailures++;
        unexpectedErrorRate.add(1);
        workUnexpectedErrors.push(Date.now());
        return { denied: true, csrf: csrf };
      }
    } catch (e) {
      // fall through
    }
  }

  workUnexpectedFailures++;
  unexpectedErrorRate.add(1);
  workUnexpectedErrors.push(Date.now());
  return { success: false, csrf: csrf };
}

function performWorkWithRetry(csrf) {
  let currentCsrf = csrf;
  let retries = 0;

  while (retries <= maxRetries429) {
    const result = doWork(currentCsrf);

    if (result.success) {
      return { success: true, csrf: result.csrf };
    }

    if (result.scheduled429) {
      retries++;
      if (retries > maxRetries429) {
        return { success: false, csrf: currentCsrf };
      }
      sleep(result.retryAfter || retryAfterSeconds);
      continue;
    }

    if (result.expired) {
      const newCsrf = renewSession(currentCsrf);
      if (newCsrf) {
        currentCsrf = newCsrf;
        const retryResult = doWork(currentCsrf);
        if (retryResult.success) {
          return { success: true, csrf: retryResult.csrf };
        }
        if (retryResult.scheduled429) {
          retries++;
          if (retries > maxRetries429) {
            return { success: false, csrf: currentCsrf };
          }
          sleep(retryResult.retryAfter || retryAfterSeconds);
          continue;
        }
      }
      return { success: false, csrf: currentCsrf };
    }

    if (result.sessionRevoked) {
      return { success: false, csrf: currentCsrf, sessionRevoked: true };
    }

    return { success: false, csrf: currentCsrf };
  }

  return { success: false, csrf: currentCsrf };
}

function runJourney(userIndex, iterationIndex) {
  const username = `bench-${(userIndex % 16) + 1}`;
  const profile = getProfile(userIndex);

  const loginResult = login(username, 'bench');
  if (!loginResult) {
    return;
  }

  let csrf = loginResult.csrf;
  let cartId = null;
  let cartEtag = null;
  let grantId = null;

  // Try to get a grant via challenge
  const challengeForm = getChallengeForm(csrf);
  if (challengeForm) {
    const challengeResult = postChallenge(challengeForm.action, challengeForm.challenge, csrf);
    if (challengeResult) {
      grantId = challengeResult.grant_id;
      csrf = challengeResult.csrf;
    }
  }

  // Get catalog
  let products = getCatalog(profile);
  if (!products || products.length === 0) {
    // Try catalog page
    const pageResult = getCatalogPage(profile, '/v2/catalog/page');
    if (pageResult && pageResult.data && pageResult.data.products) {
      products = pageResult.data.products;
    }
  }

  if (!products || products.length === 0) {
    return;
  }

  // Pick a product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;

  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    return;
  }

  // Create cart
  const cartResult = createCart(csrf, selectedProduct.id, selectedVariant.id, grantId);
  if (!cartResult) {
    return;
  }

  cartId = cartResult.id;
  csrf = cartResult.csrf;
  cartEtag = cartResult.etag;

  // Patch cart
  const quantity = randomIntBetween(1, 20);
  let patchResult = patchCart(cartId, csrf, cartEtag, quantity);

  if (patchResult && patchResult.conflict) {
    // Re-read and retry once
    const cartInfo = getCart(cartId, csrf);
    if (cartInfo) {
      cartEtag = cartInfo.etag;
      patchResult = patchCart(cartId, csrf, cartEtag, quantity);
    }
  }

  if (patchResult && !patchResult.conflict) {
    csrf = patchResult.csrf;
    cartEtag = patchResult.etag;
  }

  // Create reservation
  let reservationId = null;
  const reservationResult = createReservation(cartId, csrf);
  if (reservationResult) {
    csrf = reservationResult.csrf;
    const pollResult = pollReservation(reservationResult.status_url, csrf);
    if (pollResult) {
      reservationId = pollResult.reservation_id;
      csrf = pollResult.csrf;
    }
  }

  // Create order
  const idempotencyKey = `cart-${cartId}-${iterationIndex}-${userIndex}`;
  const orderResult = createOrder(cartId, csrf, cartEtag, reservationId, idempotencyKey);

  if (orderResult && orderResult.accepted) {
    csrf = orderResult.csrf;
  }

  // Perform work
  const workResult = performWorkWithRetry(csrf);

  if (workResult.success) {
    csrf = workResult.csrf;
  }

  // Record owner seed
  if (!ownerSeeds.has(username)) {
    ownerSeeds.set(username, {
      user: username,
      csrf: csrf,
      cartId: cartId,
      timestamp: Date.now()
    });
  }
}

export function setup() {
  // No setup needed
  return {};
}

export default function(data) {
  const vuId = __VU;
  const iterId = __ITER;

  const userIndex = (vuId - 1) % users;
  const iterationIndex = iterId;

  runJourney(userIndex, iterationIndex);

  // Sleep to control rate
  sleep(0.1);
}

export function teardown(data) {
  // Record owner seeds
  console.log('OWNER_SEEDS_START');
  for (const [username, seed] of ownerSeeds) {
    console.log(JSON.stringify({ username, seed }));
  }
  console.log('OWNER_SEEDS_END');

