  const totalWorkAttempts = workBusinessResponses;
  const unexpectedFailures = workUnexpectedFailures;
  const scheduled429Count = workScheduled429.length;
  const successCount = workCompletions.length;

  console.log(`WORK_METRICS: total=${totalWorkAttempts} success=${successCount} scheduled429=${scheduled429Count} unexpected=${unexpectedFailures}`);

  if (totalWorkAttempts > 0) {
    const failureRate = unexpectedFailures / totalWorkAttempts;
    console.log(`UNEXPECTED_FAILURE_RATE: ${failureRate}`);
  }

  // Calculate burst metrics
  if (workStartTimes.length > 0) {
    const sortedTimes = workStartTimes.slice().sort((a, b) => a - b);
    const firstTime = sortedTimes[0];
    const lastTime = sortedTimes[sortedTimes.length - 1];
    const duration = lastTime - firstTime;

    if (duration > 0) {
      const rate = (sortedTimes.length / duration) * 1000;
      console.log(`WORK_RATE: ${rate.toFixed(2)}/s over ${duration}ms`);
    }

    // Check 1-second bursts
    const burstWindows = new Map();
    for (const t of sortedTimes) {
      const windowStart = Math.floor(t / 1000) * 1000;
      if (!burstWindows.has(windowStart)) {
        burstWindows.set(windowStart, 0);
      }
      burstWindows.set(windowStart, burstWindows.get(windowStart) + 1);
    }

    for (const [windowStart, count] of burstWindows) {
      console.log(`BURST_WINDOW_${windowStart}: ${count}`);
    }
  }
