function getCart(cartId, csrf) {
  const cartRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'cart-get' }
  });

  if (cartRes.status === 200) {
    return {
      etag: cartRes.headers['ETag'] || null,
      csrf: csrf
    };
  }

  return null;
}

function patchCart(cartId, csrf, etag, quantity) {
  const patchRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
    quantity: quantity
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    tags: { name: 'cart-patch' }
  });

  if (patchRes.status === 200) {
    try {
      const body = JSON.parse(patchRes.body);
      return {
        csrf: body.csrf || csrf,
        etag: patchRes.headers['ETag'] || etag
      };
    } catch (e) {
      return { csrf: csrf, etag: etag };
    }
  }

  if (patchRes.status === 412) {
    return { conflict: true, csrf: csrf, etag: etag };
  }

