  });

  if (postRes.status === 302) {
    const location = postRes.headers['Location'];
    if (location) {
      const followRes = http.get(`${BASE_URL}${location}`, {
        headers: { 'X-CSRF-Token': csrf },
        tags: { name: 'challenge-follow' }
      });

      if (followRes.status === 200) {
        try {
          const body = JSON.parse(followRes.body);
          return {
            grantId: body.grant_id,
            csrf: body.csrf || csrf
          };
        } catch (e) {
          return null;
        }
      }
    }
  }

  return null;
}

function createReservation(cartId, csrf) {
  const resRes = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({
    cart_id: cartId
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'reservation-create' }
  });

  if (resRes.status === 202) {
    try {
      const body = JSON.parse(resRes.body);
      return {
        statusUrl: body.status_url,
        csrf: body.csrf || csrf
      };
    } catch (e) {
      return null;
    }
  }

