}

function pollReservation(statusUrl, csrf) {
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const pollRes = http.get(`${BASE_URL}${statusUrl}`, {
      headers: { 'X-CSRF-Token': csrf },
      tags: { name: 'reservation-poll' }
    });

    if (pollRes.status === 200) {
      try {
        const body = JSON.parse(pollRes.body);
        if (body.status === 'ready') {
          return {
            reservationId: body.reservation_id,
            csrf: body.csrf || csrf
          };
        }
        if (body.status === 'failed') {
          return null;
        }
      } catch (e) {
        return null;
      }
    }
  }

  return null;
}

function createOrder(cartId, csrf, etag, reservationId, idempotencyKey) {
  const payload = {
    cart_id: cartId,
    Idempotency-Key: idempotencyKey
  };

  if (reservationId) {
    payload.reservation_id = reservationId;
  }

  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
      'Idempotency-Key': idempotencyKey
    },
    tags: { name: 'order-create' }
  });

  if (orderRes.status === 201) {
    try {
      const body = JSON.parse(orderRes.body);
      if (body.accepted === true) {
        return {
          success: true,
          csrf: body.csrf || csrf,
          orderId: body.id
        };
      }
      return { success: false, csrf: body.csrf || csrf };
    } catch (e) {
      return null;
    }
  }

  if (orderRes.status === 200) {
    try {
      const body = JSON.parse(orderRes.body);
      if (body.accepted === false) {
        return { success: false, csrf: body.csrf || csrf };
      }
      return { success: true, csrf: body.csrf || csrf };
    } catch (e) {
      return null;
    }
  }

  return null;
}

function doWork(csrf) {
  let attempts = 0;
  let lastCsrf = csrf;

  while (attempts < 4) {
    const workRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': lastCsrf
      },
      tags: { name: 'work' }
    });

    if (workRes.status === 200) {
      try {
        const body = JSON.parse(workRes.body);
        if (body.ok === true) {
          workSuccess.add(1);
          return { success: true, csrf: body.csrf || lastCsrf };
        }
      } catch (e) {
        workUnexpected.add(1);
        businessFailure.add(1);
        return { success: false, csrf: lastCsrf };
      }
    }

    if (workRes.status === 429) {
      const retryAfter = workRes.headers['Retry-After'];
      const waitTime = retryAfter ? parseInt(retryAfter) : 1;
      sleep(waitTime);
      attempts++;
      continue;
    }

    if (workRes.status === 401) {
      try {
        const body = JSON.parse(workRes.body);
        if (body.error === 'expired') {
          const newCsrf = renewSession(lastCsrf);
          if (newCsrf) {
            lastCsrf = newCsrf;
            attempts++;
            continue;
          }
        }
      } catch (e) {
        // fall through
      }
      workUnexpected.add(1);
      businessFailure.add(1);
      return { success: false, csrf: lastCsrf };
    }

    if (workRes.status === 500) {
      workUnexpected.add(1);
      businessFailure.add(1);
      return { success: false, csrf: lastCsrf };
    }

    workUnexpected.add(1);
    businessFailure.add(1);
    return { success: false, csrf: lastCsrf };
  }

  workUnexpected.add(1);
  businessFailure.add(1);
  return { success: false, csrf: lastCsrf };
}

export const options = {
  scenarios: {
    work_load: {
      executor: 'constant-arrival-rate',
      rate: 10,
      timeUnit: '1s',
      duration: '45s',
      preAllocatedVUs: 32,
      maxVUs: 32,
      exec: 'workJourney'
    }
  },
  thresholds: {
    'dropped_iterations': ['count<1'],
    'business_failure': ['rate<0.01']
  }
};

export function workJourney() {
  const profile = getProfile();
  const userIdx = (__VU - 1) % users.length;
  const username = users[userIdx];

  const loginResult = login(username);
  if (!loginResult) {
    droppedIterations.add(1);
    return;
  }

  let csrf = loginResult.csrf;
  let cartId = null;
  let cartEtag = null;
  let grantId = null;
  let reservationId = null;
  let idempotencyKey = `idem-${__VU}-${__ITER}-${Date.now()}`;

  // Get catalog
  const products = getCatalog(csrf, profile);
  if (!products || products.length === 0) {
    droppedIterations.add(1);
    return;
  }

  let selectedProduct = null;
  let selectedVariant = null;

  // Try to find a product with in-stock variant
  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }

  // If no in-stock variant, try catalog pages
  if (!selectedProduct) {
    let pageUrl = '/v2/catalog/page';
    for (let i = 0; i < 3 && !selectedProduct; i++) {
      const pageData = getCatalogPage(csrf, pageUrl);
      if (!pageData) break;

      if (pageData.data && pageData.data.products) {
        for (const product of pageData.data.products) {
          if (product.variants && product.variants.length > 0) {
            for (const variant of product.variants) {
              if (variant.in_stock) {
                selectedProduct = product;
                selectedVariant = variant;
                break;
              }
            }
            if (selectedProduct) break;
          }
        }
      }

      if (!pageData.next) break;
      pageUrl = pageData.next;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    droppedIterations.add(1);
    return;
  }

  // Try to get challenge/grant
  const challengeForm = getChallengeForm(csrf);
  if (challengeForm) {
    const challengeResult = postChallenge(challengeForm.action, challengeForm.challenge, csrf);
    if (challengeResult) {
      grantId = challengeResult.grantId;
      csrf = challengeResult.csrf;
    }
  }

  // Create cart
  const cartResult = createCart(csrf, selectedProduct.id, selectedVariant.id, grantId);
  if (!cartResult) {
    droppedIterations.add(1);
    return;
  }

  cartId = cartResult.id;
  csrf = cartResult.csrf;
  cartEtag = cartResult.etag;

  // Get cart to get ETag if not present
  if (!cartEtag) {
    const cartGetResult = getCart(cartId, csrf);
    if (cartGetResult) {
      cartEtag = cartGetResult.etag;
    }
  }

  // Patch cart
  if (cartEtag) {
    const patchResult = patchCart(cartId, csrf, cartEtag, 1);
    if (patchResult) {
      if (patchResult.conflict) {
        // Re-read and retry once
        const reReadResult = getCart(cartId, csrf);
        if (reReadResult && reReadResult.etag) {
          const retryPatch = patchCart(cartId, csrf, reReadResult.etag, 1);
          if (retryPatch && !retryPatch.conflict) {
            csrf = retryPatch.csrf;
            cartEtag = retryPatch.etag;
          } else if (retryPatch && retryPatch.conflict) {
            // Give up on patch, continue with current etag
            cartEtag = reReadResult.etag;
          }
        }
      } else {
        csrf = patchResult.csrf;
        cartEtag = patchResult.etag;
      }
    }
  }

  // Create reservation
  const reservationResult = createReservation(cartId, csrf);
  if (reservationResult) {
    csrf = reservationResult.csrf;
    const pollResult = pollReservation(reservationResult.statusUrl, csrf);
    if (pollResult) {
      reservationId = pollResult.reservationId;
      csrf = pollResult.csrf;
    }
  }

  // Create order
  if (cartEtag) {
    const orderResult = createOrder(cartId, csrf, cartEtag, reservationId, idempotencyKey);
    if (orderResult) {
      csrf = orderResult.csrf;
      if (!orderResult.success) {
        // Business failure - not a success, but not a dropped iteration
        // Still do work
      }
    }
  }

  // Do work
  const workResult = doWork(csrf);
  if (!workResult.success) {
    droppedIterations.add(1);
  }

  // Simulate latency based on profile
  const elapsed = (Date.now() - globalThis.__T0) / 1000;
  if (elapsed > profile.slow_after_seconds) {
    sleep(profile.slow_seconds);
  } else {
    sleep(profile.delay_seconds);
  }
}

export function setup() {
  globalThis.__T0 = Date.now();
  return {};
}
