        }
      }
    }
  } else if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      return {
        csrf: body.csrf,
        user: body.user,
        cookies: res.cookies
      };
    } catch (e) {
      return null;
    }
  }

  return null;
}

// Helper: renew session
function renewSession(csrf) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
