// Helper: create cart
function createCart(csrf, productId, variantId, grantId = null) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };
  if (grantId) {
    payload.grant_id = grantId;
  }

  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'cart_create' }
  });

  if (res.status === 201) {
    try {
      const body = JSON.parse(res.body);
      return {
        id: body.id,
        csrf: body.csrf || csrf,
        etag: res.headers['ETag']
      };
    } catch (e) {
      return null;
    }
  }

  return null;
}

// Helper: get cart
function getCart(cartId, csrf) {
  const res = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: {
      'X-CSRF-Token': csrf
    },
    tags: { name: 'cart_get' }
  });

  if (res.status === 200) {
    return {
      etag: res.headers['ETag'],
      csrf: csrf
    };
  }

  return null;
}

// Helper: patch cart
function patchCart(cartId, csrf, etag, quantity) {
  const res = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
    quantity: quantity
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    tags: { name: 'cart_patch' }
  });

  if (res.status === 412) {
    // Re-read and retry once
    const cartInfo = getCart(cartId, csrf);
    if (cartInfo) {
      const retryRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
        quantity: quantity
      }), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
          'If-Match': cartInfo.etag
        },
        tags: { name: 'cart_patch_retry' }
      });
      return retryRes.status < 400;
    }
    return false;
  }

  return res.status < 400;
}

// Helper: get challenge form
function getChallengeForm(csrf) {
  const res = http.get(`${BASE_URL}/v2/challenge-form`, {
    headers: {
      'X-CSRF-Token': csrf
    },
    tags: { name: 'challenge_form' }
  });

  if (res.status !== 200) {
    return null;
  }

  // Extract form action and challenge input
  const actionMatch = res.body.match(/action=["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
  const challengeMatch = res.body.match(/name=["']challenge["']/i);

  if (!actionMatch || !challengeMatch) {
    return null;
  }

  return {
    action: actionMatch[1],
    hasChallengeInput: true
  };
}

// Helper: post challenge
function postChallenge(csrf, action) {
  const res = http.post(`${BASE_URL}${action}`, JSON.stringify({
    challenge: 'bench'
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'challenge_post' }
  });

  if (res.status === 302) {
    const location = res.headers['Location'];
    if (location) {
      const redirectRes = http.get(`${BASE_URL}${location}`, {
        headers: {
          'X-CSRF-Token': csrf
        },
        tags: { name: 'challenge_redirect' }
      });
      if (redirectRes.status === 200) {
        try {
          const body = JSON.parse(redirectRes.body);
          return {
            grant_id: body.grant_id,
            csrf: body.csrf || csrf
          };
        } catch (e) {
          return null;
        }
      }
    }
  }

  return null;
}

// Helper: create reservation
function createReservation(cartId, csrf) {
  const res = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({
    cart_id: cartId
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
