        csrf: body.csrf || csrf
      };
    } catch (e) {
      return null;
    }
  }

  return null;
}

// Helper: poll reservation
function pollReservation(statusUrl, csrf) {
  for (let i = 0; i < 5; i++) {
    sleep(0.05); // at least 50ms apart
    const res = http.get(`${BASE_URL}${statusUrl}`, {
      headers: {
        'X-CSRF-Token': csrf
      },
      tags: { name: 'reservation_poll' }
    });

    if (res.status === 200) {
      try {
        const body = JSON.parse(res.body);
        if (body.status === 'ready') {
          return {
            reservation_id: body.reservation_id,
            csrf: body.csrf || csrf
          };
        } else if (body.status === 'failed') {
          return null;
        }
        // pending - continue polling
      } catch (e) {
        return null;
      }
    }
  }

  return null;
}

// Helper: create order (checkout)
function createOrder(cartId, csrf, reservationId = null, idempotencyKey = null) {
  const payload = {
    cart_id: cartId
  };
  if (reservationId) {
    payload.reservation_id = reservationId;
  }

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey || `key-${Date.now()}-${Math.random()}`
  };

  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
    tags: { name: 'order_create' }
  });

  if (res.status === 201) {
    try {
      const body = JSON.parse(res.body);
      if (body.accepted === true) {
        return {
          success: true,
          csrf: body.csrf || csrf,
          orderId: body.id
        };
      }
    } catch (e) {
      return { success: false };
    }
  }

  return { success: false };
}

// Helper: browse operation
function browseOperation(csrf) {
  const res = http.post(`${BASE_URL}/v2/browse`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'browse' }
  });

  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.ok === true) {
        return { success: true, csrf: body.csrf || csrf };
      }
    } catch (e) {
      return { success: false };
    }
  } else if (res.status === 429) {
    // Scheduled 429 - retry with Retry-After
    const retryAfter = parseInt(res.headers['Retry-After'] || '1');
    for (let i = 0; i < 4; i++) {
      sleep(retryAfter);
      const retryRes = http.post(`${BASE_URL}/v2/browse`, JSON.stringify({}), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf
        },
        tags: { name: 'browse_retry' }
      });
      if (retryRes.status === 200) {
        try {
          const body = JSON.parse(retryRes.body);
          if (body.ok === true) {
            return { success: true, csrf: body.csrf || csrf };
          }
        } catch (e) {
          return { success: false };
        }
      } else if (retryRes.status !== 429) {
        return { success: false };
      }
    }
    return { success: false };
  }

  return { success: false };
}

