// Helper: handle 401 error
function handle401Error(errorType, csrf, cartId = null) {
  if (errorType === 'expired') {
    // Renew session
    const newCsrf = renewSession(csrf);
    if (newCsrf) {
      if (cartId) {
        recoverCart(cartId, newCsrf);
      }
      return { success: true, csrf: newCsrf };
    }
  } else if (errorType === 'session') {
    // Session revoked - get fresh login
    const form = getLoginForm();
    if (form) {
      const loginResult = login(getRandomAccount(), 'bench', form.csrf);
      if (loginResult) {
        if (cartId) {
          recoverCart(cartId, loginResult.csrf);
        }
        return { success: true, csrf: loginResult.csrf };
      }
    }
  }

  return { success: false, csrf: csrf };
}

// Helper: parse 401 error type from response body
function parse401Error(body) {
  try {
    const parsed = JSON.parse(body);
    if (parsed.error === 'expired') return 'expired';
    if (parsed.error === 'session') return 'session';
    if (parsed.error === 'denied') return 'denied';
  } catch (e) {
    // Try to find error in body
    if (body.includes('expired')) return 'expired';
    if (body.includes('session')) return 'session';
    if (body.includes('denied')) return 'denied';
  }
  return 'unknown';
}

// Helper: complete checkout journey
function checkoutJourney() {
  const startTime = Date.now();
  let csrf = null;
  let cartId = null;
  let cartEtag = null;
  let grantId = null;
  let reservationId = null;
  let idempotencyKey = `order-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

  // Fresh login
  const form = getLoginForm();
  if (!form) {
    droppedWork.add(1);
    totalWork.add(1);
    return;
  }

  const loginResult = login(getRandomAccount(), 'bench', form.csrf);
  if (!loginResult) {
    droppedWork.add(1);
    totalWork.add(1);
    return;
  }
  csrf = loginResult.csrf;

  // Get catalog
  const products = getCatalog(csrf, profile.reverse_catalog || false);
  if (!products || products.length === 0) {
    droppedWork.add(1);
    totalWork.add(1);
    return;
  }

  // Select a product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;

  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    // Try catalog pages
    let pageUrl = '/v2/catalog/page';
    for (let i = 0; i < 3; i++) {
      const pageData = getCatalogPage(csrf, pageUrl);
      if (!pageData) break;

      if (pageData.data && pageData.data.products) {
        for (const product of pageData.data.products) {
          if (product.variants && product.variants.length > 0) {
            for (const variant of product.variants) {
              if (variant.in_stock) {
                selectedProduct = product;
                selectedVariant = variant;
                break;
              }
            }
            if (selectedProduct) break;
          }
        }
      }

      if (selectedProduct) break;
      if (!pageData.next) break;
      pageUrl = pageData.next;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    droppedWork.add(1);
    totalWork.add(1);
    return;
  }

  // Try to get challenge/grant
  const challengeForm = getChallengeForm(csrf);
  if (challengeForm) {
    const challengeResult = postChallenge(csrf, challengeForm.action);
    if (challengeResult) {
      grantId = challengeResult.grant_id;
      csrf = challengeResult.csrf;
    }
  }

  // Create cart
  const cartResult = createCart(csrf, selectedProduct.id, selectedVariant.id, grantId);
  if (!cartResult) {
    droppedWork.add(1);
    totalWork.add(1);
    return;
  }
  cartId = cartResult.id;
  csrf = cartResult.csrf;
  cartEtag = cartResult.etag;

  // Patch cart quantity
  const quantity = randomIntBetween(1, 20);
  const patchSuccess = patchCart(cartId, csrf, cartEtag, quantity);
  if (!patchSuccess) {
    droppedWork.add(1);
    totalWork.add(1);
    return;
  }

  // Get updated cart etag
  const updatedCart = getCart(cartId, csrf);
  if (updatedCart) {
    cartEtag = updatedCart.etag;
  }

  // Create reservation
  const reservationResult = createReservation(cartId, csrf);
  if (reservationResult) {
    csrf = reservationResult.csrf;
    const pollResult = pollReservation(reservationResult.status_url, csrf);
    if (pollResult) {
      reservationId = pollResult.reservation_id;
      csrf = pollResult.csrf;
    }
  }

  // Checkout delay
  const currentTime = Date.now();
  const elapsedSeconds = (currentTime - startTime) / 1000;
  let delaySeconds = profile.checkout_delay_seconds;
  if (elapsedSeconds > profile.checkout_slow_after_seconds) {
    delaySeconds = profile.checkout_slow_seconds;
  }
  sleep(delaySeconds);

  // Create order
  const orderResult = createOrder(cartId, csrf, reservationId, idempotencyKey);

  if (orderResult.success) {
    checkoutStarts.add(1);
    completedWork.add(1);
    totalWork.add(1);
  } else {
    droppedWork.add(1);
    totalWork.add(1);
  }
}

// Helper: browse journey
function browseJourney() {
  let csrf = null;

  // Fresh login
  const form = getLoginForm();
  if (!form) {
    droppedWork.add(1);
